messages.content:
Tool response:
Tool: search_new_inventory
Description: Search New Inventory
Parameters:
    {
      "type": "object",
      "properties": {
        "make": {
          "type": "string",
          "description": "Vehicle manufacturer",
          "title": "Make"
        },
        "model": {
          "type": "string",
          "description": "Vehicle model",
          "title": "Model"
        },
        "year": {
          "type": "integer",
          "description": "Vehicle year",
          "title": "Year"
        },
        "fuel_type": {
          "type": "string",
          "description": "Fuel type of vehicle",
          "title": "Fuel Type"
        },
        "max_price": {
          "type": "number",
          "description": "Maximum price threshold",
          "title": "Max Price"
        },
        "city": {
          "type": "string",
          "description": "City for location-based filtering",
          "title": "City"
        },
        "state": {
          "type": "string",
          "description": "State for location-based filtering",
          "title": "State"
        },
        "radius_miles": {
          "type": "integer",
          "description": "Search radius in miles",
          "title": "Radius Miles"
        },
        "sort_by": {
          "anyOf": [
            {
              "type": "string"
            },
            {
              "type": "null"
            }
          ],
          "description": "Sorting criteria (default: price_asc)",
          "title": "Sort By"
        }
      },
      "required": [
        "make",
        "model",
        "year",
        "fuel_type",
        "max_price",
        "city",
        "state",
        "radius_miles"
      ]
    }
